 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The two patterned bands are copies; align the lower band with the upper
    # band by the horizontal offset that maximizes matching foreground cells.
    # Mark reference foreground cells missing from the lower copy.
    split = h // 2
    top_rows = [r for r in range(split) if any(v != 9 for v in grid[r])]
    bot_rows = [r for r in range(split, h) if any(v != 9 for v in grid[r])]
    if not top_rows or not bot_rows:
        return out
    n = min(len(top_rows), len(bot_rows))
    top_rows, bot_rows = top_rows[:n], bot_rows[-n:]
    best = None
    for dx in range(-w + 1, w):
        score = 0
        for a, b in zip(top_rows, bot_rows):
            for c in range(w):
                cc = c + dx
                if 0 <= cc < w and grid[a][c] != 9 and grid[b][cc] == grid[a][c]:
                    score += 1
        if best is None or score > best[0]:
            best = (score, dx)
    dx = best[1]
    for a, b in zip(top_rows, bot_rows):
        for c in range(w):
            cc = c + dx
            if 0 <= cc < w and grid[a][c] != 9 and grid[b][cc] == 9:
                out[b][cc] = 1
    return out
